import { Injectable, inject } from '@angular/core';
import { Observable, of } from 'rxjs';

import { isNullOrUndefined } from '../../../../shared/utils';
import {
  MapSetListItem,
  MapSetResponse,
  MapsetUpdateRequest,
  EntitiesService,
} from '../../../../api';
import {
  DataGridParams,
  EntityDataAdapter,
  GridResponse,
} from '../../../../shared/models';
import { ActionIcon, EntityConfigAdapter, StateOption } from '../../models';
import { EntityDetailsStateService } from '../entity/entity-details.state.service';
import { AuthDataService } from '../../../../core/services/auth-data.service';

@Injectable({
  providedIn: 'root',
})
export class MapSetsDataAdapter
  implements
    EntityDataAdapter<MapSetListItem, MapSetResponse>,
    EntityConfigAdapter
{
  private readonly entitiesService = inject(EntitiesService);
  private readonly entityStateService = inject(EntityDetailsStateService);
  private readonly authDataService = inject(AuthDataService);

  getList(params: DataGridParams): Observable<GridResponse<MapSetListItem>> {
    const { owner, limit, offset, sortField, filters } = params;

    if (isNullOrUndefined(owner)) {
      return of({ items: [], count: 0 });
    }

    return this.entitiesService.listMapSets(
      owner,
      offset,
      limit,
      sortField as string,
      filters,
    );
  }

  getById(id: string): Observable<MapSetResponse> {
    return this.entitiesService.getMapSet(id);
  }

  getStateOptions(): StateOption[] {
    return [
      {
        label: 'Active',
        value: MapSetResponse.StateEnum.Active,
      },
      {
        label: 'Deleted',
        value: MapSetResponse.StateEnum.Deleted,
      },
    ];
  }

  updateState(id: string, state: unknown): Observable<unknown> {
    return this.entitiesService.updateMapSet(id, {
      state: state as MapsetUpdateRequest.StateEnum,
    });
  }

  getActionIcons(_entityId: string): ActionIcon[] {
    if (!this.authDataService.hasPermission('mapset:create')) {
      return [];
    }

    return [
      {
        id: 'changeState',
        icon: 'pi pi-trash',
        tooltip: 'Change Map Set State',
        visible: true,
        showPopover: true,
        popoverType: 'state',
        action: () => {
          this.entityStateService.togglePopover('changeState');
        },
      },
    ];
  }
}
