import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import {
  EmailProviderListItem,
  EmailProvidersService,
  EmailProviderListResponse,
  EntitiesService,
} from '../../../../api';
import { GridDataService } from '../../../../shared/models';
import { EmailProviderResponse } from '../../../../api';
import { ActionIcon, EntityConfigAdapter, StateOption } from '../../models';
import { AuthDataService } from '../../../../core/services/auth-data.service';
import { EntityDetailsStateService } from '../entity/entity-details.state.service';

@Injectable({
  providedIn: 'root',
})
export class EmailProvidersDataAdapter
  implements GridDataService<EmailProviderListItem>, EntityConfigAdapter
{
  private readonly service = inject(EmailProvidersService);
  private readonly entitiesService = inject(EntitiesService);
  private readonly authDataService = inject(AuthDataService);
  private readonly entityStateService = inject(EntityDetailsStateService);

  getList(params: {
    owner: string;
    offset: number;
    page: number;
    limit: number;
    sortField?: string;
    sortOrder?: number;
    filters?: string;
    recurse?: boolean;
  }): Observable<EmailProviderListResponse> {
    return this.service.listEmailProviders(
      params.owner,
      params.offset,
      params.limit,
      params.sortField,
      params.filters,
    );
  }

  getById(id: string): Observable<EmailProviderResponse> {
    return this.service.getEmailProvider(id);
  }

  getStateOptions(): StateOption[] {
    return [
      { label: 'Active', value: EmailProviderResponse.StateEnum.Active },
      { label: 'Suspended', value: EmailProviderResponse.StateEnum.Suspended },
      { label: 'Deleted', value: EmailProviderResponse.StateEnum.Deleted },
    ];
  }

  updateState(id: string, state: unknown): Observable<unknown> {
    return this.entitiesService.updateEmailProvider(id, {
      state: state as EmailProviderResponse.StateEnum,
    });
  }

  getActionIcons(_entityId: string): ActionIcon[] {
    // `client:emailProviders` covers create/modify/delete (see LEGACY_RIGHTS).
    if (!this.authDataService.hasPermission('client:emailProviders')) {
      return [];
    }

    return [
      {
        id: 'changeState',
        icon: 'pi pi-trash',
        tooltip: 'Change Email Provider State',
        visible: true,
        showPopover: true,
        popoverType: 'state',
        action: () => {
          this.entityStateService.togglePopover('changeState');
        },
      },
    ];
  }
}
