import { Component, ViewChild, AfterViewInit, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

import { DynamicDialogRef, DynamicDialogConfig } from 'primeng/dynamicdialog';
import { DynamicFormComponent } from '../../../../../shared/components/forms/dynamic-form/dynamic-form.component';
import { TranslateService } from '@ngx-translate/core';

import { EntitiesService } from '../../../../../api';

import { KindOfCharacterAttributes, NgTerminal, NgTerminalModule } from 'ng-terminal';
import { FunctionsUsingCSI } from 'ng-terminal';

import { FormAction, FormFieldConfig } from '../../../../../shared/models';

import { WebSocketService } from '../../../../../core/services/websocket.service';

import { environment } from '../../../../../../environments/environment';

@Component({
  selector: 'app-device-console',
  imports: [
    DynamicFormComponent,
    NgTerminalModule
  ],
  templateUrl: './device-console.component.html',
  styleUrl: './device-console.component.scss',
  // Own instance rather than the root singleton: system health also connects through this
  // service, and sharing one socket slot means whichever opens last orphans the other's
  // connection. A component-scoped instance also gets closed when the dialog is destroyed.
  providers: [WebSocketService],
})
export class DeviceConsoleComponent implements AfterViewInit{
  private readonly dialogRef = inject(DynamicDialogRef);
  private readonly dialogConfig = inject(DynamicDialogConfig);
  private readonly entitiesService = inject(EntitiesService);
  protected readonly translate = inject(TranslateService);

  private readonly wsService = inject(WebSocketService);

  protected actions: FormAction[] = this.buildDefaultActions();
  protected formFields: FormFieldConfig[] = [];

  private deviceID = this.dialogConfig.data.deviceID;
  private connStatus = false;
  private promptChar = "  ";
  private statusNumber = -1;

  command = signal(''); 

  @ViewChild('term', { static: false }) child?: NgTerminal;

  constructor() {
    // The dialog hands us the device's entity UUID, but the console worker addresses
    // devices by IMEI -- DeviceResponse.name holds "the serial or IMEI of the device",
    // so resolve the UUID to that before opening the socket.
    this.entitiesService
      .getDevice(this.deviceID)
      .pipe(takeUntilDestroyed())
      .subscribe({
        next: (device) => this.connect(device.name),
        error: () => this.connect(null),
      });
  }

  // Opens the websocket against the console worker for a given device IMEI. The base
  // URL is environment-specific (see src/environments/environment*.ts).
  private connect(imei: string | null | undefined): void {
    if (imei == null || imei === '') {
      this.child?.write('  Could not resolve the device IMEI\r\n' + this.promptChar);
      return;
    }

    this.wsService.connect({
      url: `${environment.deviceConsoleWsUrl}?device=${encodeURIComponent(imei)}`,
      reconnectInterval: 1000,
      reconnectAttempts: 10,
    });
  }

  buildDefaultActions(): FormAction[] {
    return [
      {
        label: this.translate.instant('SHARED.COMMON.BUTTONS.CANCEL'),
        action: () => this.onCancel(),
        severity: 'primary',
      },
    ];
  }

  onCancel(): void {
    // No need to disconnect here: the service closes its socket when this component's
    // injector is destroyed, which also covers closing via the header X or Escape.
    this.dialogRef.close();
  }

  ngAfterViewInit() {
    this.child?.write(this.promptChar + 'Getting device id...\r\n'+ this.promptChar);

    // Prefixes for changing various terminal attributes. These can be printed directly to set
    // the color, or to change between bold and normal text.
    const fgGreen  = FunctionsUsingCSI.characterAttributes(KindOfCharacterAttributes.SetforegroundcolortoGreen);
    const fgYellow = FunctionsUsingCSI.characterAttributes(KindOfCharacterAttributes.SetforegroundcolortoYellow);
    const fgRed    = FunctionsUsingCSI.characterAttributes(KindOfCharacterAttributes.SetforegroundcolortoRed);
    const fgWhite  = FunctionsUsingCSI.characterAttributes(KindOfCharacterAttributes.SetforegroundcolortoWhite);

    const chBold   = FunctionsUsingCSI.characterAttributes(KindOfCharacterAttributes.Bold);
    const chNormal = FunctionsUsingCSI.characterAttributes(KindOfCharacterAttributes.Normal);

    // Prefixes for informational, warning, error and server messages
    const info  = fgGreen + '[INFO]' + fgWhite    + ':  ';
    const warn  = fgYellow+ '[WARN]' + fgWhite    + ':  ';
    const error = fgRed   + '[ERROR]' + fgWhite   + ': ';
    const server= chBold  + '[SERVER]' + chNormal + ':';

    // On every connectivity transition, this lambda function is called to update the connection status
    // This is used to manage whether the user can type, and to show informational messages
    this.wsService.status$.subscribe((connected) => {
      // Visually change the prompt to signal whether typing is enabled or not
      if (!connected) {
        this.promptChar = "  ";
        this.child?.setXtermOptions({cursorStyle: 'underline', cursorBlink: false});
      } 
      else {
        this.promptChar = "$ ";
        this.child?.setXtermOptions({cursorStyle: 'block', cursorBlink: true});
      } 
      
      // Print status messages as the connectivity state changes
      if (this.statusNumber < 0) {
        this.statusNumber += 1; // wsService immediately sends an annoying disconnected status when you subscribe...
      }
      else if (connected && this.connStatus == false) {
        this.connStatus = true;
        this.child?.write(info + 'Successfully connected to WSS server\r\n'+ this.promptChar);
      }
      else if (!connected && this.connStatus == true) {
        this.connStatus = false;
        this.child?.write(warn + 'WSS server terminated connection\r\n'+ this.promptChar);
      }
      else if (!connected)
        this.child?.write(error + 'Failed to connect to WSS server\r\n'+ this.promptChar);
    })

    // When we receive responses from the server, print them as server messages
    this.wsService.messages$.subscribe((msg) => {
      this.child?.write(server + msg["response"] + ' \r\n'+ this.promptChar);
    })

    // This code is called whenever the terminal object receives a character. 
    // On a real terminal, this would be when a character is received over serial,
    // and thus this code serves to emulate a terminal's behaviour
    // THIS CODE DOES NOT MANAGE THE INTERNAL COMMAND BUFFER
    this.child?.onData().subscribe((input) => {
      if (!this.connStatus) return;

      if (!this.child) return;
      if (input === '\r') {            // Return (enter)
        this.child.write('\r\n'+ this.promptChar);
      } else if (input === '\u007f') { // Backspace
        if ((this.child.underlying?.buffer.active.cursorX ?? 0) > 2)
          this.child.write('\b \b');
      } else if (input === '\u0003') { // Ctrl+C
        this.child.write('^C');
        this.child.write('\r\n'+ this.promptChar);
      } else this.child.write(input);  // Normal key
    });

  }

  // This gets called on each keystroke from the user, and handles the
  // internal command buffer. THIS CODE DOES NOT HANDLE THE UI
  onKeyInput(event: string) {
    if (!this.connStatus) return;

    const len = this.command().length;
    if (event === '\u007f' && len > 0) // Backspace
      this.command.set(this.command().substring(0, len-1));
    else if (event === '\u0003')       // Ctrl+C (kb_interrupt, or cancel line)
      this.command.set('');
    else if (event === '\r') {         // Return (enter key)
      // The help command is handled by the front-end 
      if (this.command().toLowerCase() === 'help') {
        this.child?.write(
          '\r\n  This is the help message' +
          '\r\n  ' +
          '\r\n  Please replace it with something helpful in the future...' +
          '\r\n  kthxbye'
        )
      }
      // All other commands are handled by the server
      else {
        this.wsService.send({
          type: "command",
          ["command"]: this.command()
        })
      }

      this.command.set('');
    }
    else                               // Normal key was pressed. Just append the key to the command
      this.command.set(this.command() + event);
  }
}
