import {
  ReminderCreateRequest,
  ReminderReset,
  ReminderTriggerValue,
} from '../../../../../api';
import { ReminderType } from '../../../models';
import { isDefined } from '../../../../../shared/utils';

/**
 * Raw value produced by the dynamic reminder form, before it is mapped to a
 * {@link ReminderCreateRequest}. Fields are optional because which ones are
 * present depends on the reminder type and mode selected in the form.
 */
export interface ReminderFormData {
  name?: string | null;
  mode?: 'once' | 'repeating' | null;
  /**
   * Trigger group as it arrives from the API/form. `value`/`start` are strings
   * (odometer/hours increments or ISO dates); the mapper narrows and reformats
   * them before use.
   */
  trigger?: ReminderTriggerValue;
  triggerValue?: string | number;
  triggerStart?: string | number;
  timeZoneId?: string | null;
  resetType?: ReminderReset.TypeEnum;
  reset?: Partial<ReminderReset>;
}

export class ReminderMapper {
  static mapToApiRequest(
    formData: ReminderFormData,
    type: ReminderType,
    ownerId: string,
    target: { id: string; name: string | undefined | null },
  ): ReminderCreateRequest {
    // 1. Normalize Trigger
    const formattedTrigger = this.formatTrigger(formData, type);

    // 2. Normalize Reset
    const formattedReset = this.formatReset(formData);

    return {
      name: formData.name ?? '',
      target: { type: 'asset', id: target.id, name: target.name },
      type: type,
      mode: formData.mode,
      timeZoneId: formData.timeZoneId,
      trigger: formattedTrigger,
      reset: formattedReset,
      ownerId: ownerId,
      enabled: true,
    };
  }

  private static formatTrigger(formData: ReminderFormData, type: ReminderType) {
    let formattedTrigger = formData.trigger;
    if (!isDefined(formattedTrigger)) return undefined;

    switch (type) {
      case ReminderType.TIME_BASED:
        if (formData.mode === 'once') {
          const triggerValue = formattedTrigger.value;
          if (isDefined(triggerValue)) {
            const dateValue = this.convertToDate(triggerValue);
            if (dateValue && !Number.isNaN(dateValue.getTime())) {
              formattedTrigger = {
                ...formattedTrigger,
                value: dateValue.toISOString(),
              };
            }
          }
        } else if (formData.mode === 'repeating') {
          const triggerStart = formattedTrigger.start;
          const triggerValue = formattedTrigger.value;
          formattedTrigger = { ...formattedTrigger };
          if (isDefined(triggerValue))
            formattedTrigger.value = String(triggerValue);
          if (isDefined(triggerStart)) {
            const dateValue = this.convertToDate(triggerStart);
            if (dateValue && !Number.isNaN(dateValue.getTime())) {
              formattedTrigger.start = dateValue.toISOString();
            }
          }
        }
        break;

      case ReminderType.ODOMETER:
      case ReminderType.ENGINE_HOURS:
        if (formData.mode === 'repeating') {
          formattedTrigger = {
            value: isDefined(formData.triggerValue)
              ? String(formData.triggerValue)
              : undefined,
            start: isDefined(formData.triggerStart)
              ? String(formData.triggerStart)
              : undefined,
          };
        } else {
          formattedTrigger = { ...formattedTrigger };
          if (isDefined(formattedTrigger.value))
            formattedTrigger.value = String(formattedTrigger.value);
        }
        break;

      default:
        break;
    }
    return formattedTrigger;
  }

  private static formatReset(formData: ReminderFormData): ReminderReset {
    const resetType = formData.resetType ?? 'none';
    const defaultReset: ReminderReset = {
      type: resetType,
      counter: 1,
      daily: { recurrence: 1 },
      weekly: { days: [...new Array(7).keys()].map((x) => x) },
      monthly: { months: [...new Array(12).keys()].map((x) => ++x), day: 1 },
    };
    return { ...defaultReset, ...formData.reset, type: resetType };
  }

  private static convertToDate(value: unknown): Date | null {
    if (value instanceof Date) return value;
    if (typeof value === 'string' || typeof value === 'number') {
      const date = new Date(value);
      return Number.isNaN(date.getTime()) ? null : date;
    }
    return null;
  }
}
