import { Injectable, inject } from '@angular/core';
import { Observable, of } from 'rxjs';

import { isNullOrUndefined } from '../../../../shared/utils';
import {
  RoadProfileListItem,
  RoadProfileResponse,
  EntitiesService,
} from '../../../../api';
import {
  DataGridParams,
  EntityDataAdapter,
  GridResponse,
} from '../../../../shared/models';
import { ActionIcon, EntityConfigAdapter, StateOption } from '../../models';
import { EntityDetailsStateService } from '../entity/entity-details.state.service';

@Injectable({
  providedIn: 'root',
})
export class RoadProfilesDataAdapter
  implements
    EntityDataAdapter<RoadProfileListItem, RoadProfileResponse>,
    EntityConfigAdapter
{
  private readonly entitiesService = inject(EntitiesService);
  private readonly entityStateService = inject(EntityDetailsStateService);

  getList(
    params: DataGridParams,
  ): Observable<GridResponse<RoadProfileListItem>> {
    const { owner, limit, offset, sortField, filters, recurse } = params;

    if (isNullOrUndefined(owner)) {
      return of({ items: [], count: 0 });
    }

    return this.entitiesService.listRoadProfiles(
      owner,
      recurse,
      offset,
      limit,
      sortField as string,
      filters,
    );
  }

  getById(id: string): Observable<RoadProfileResponse> {
    return this.entitiesService.getRoadProfile(id);
  }

  getStateOptions(): StateOption[] {
    return [
      { label: 'Active', value: RoadProfileResponse.StateEnum.Active },
      { label: 'Deleted', value: RoadProfileResponse.StateEnum.Deleted },
    ];
  }

  updateState(id: string, state: unknown): Observable<unknown> {
    return this.entitiesService.updateRoadProfile(id, {
      state: state as RoadProfileResponse.StateEnum,
    });
  }

  getActionIcons(_entityId: string): ActionIcon[] {
    // TODO: Gate behind the road-profile create/update permission once the
    // correct slug is confirmed (no proven `road-profile*` permission exists in
    // the app yet; slug format also varies across adapters — dot vs colon).
    return [
      {
        id: 'changeState',
        icon: 'pi pi-trash',
        tooltip: 'Change Road Profile State',
        visible: true,
        showPopover: true,
        popoverType: 'state',
        action: () => {
          this.entityStateService.togglePopover('changeState');
        },
      },
    ];
  }
}
